import java.io.*;import java.nio.file.*;import java.util.*;
public class SalesReportDemo{
 static Path dir=Path.of("data/sales");
 static String manual(boolean fail)throws IOException{List<BufferedReader> opened=new ArrayList<>();try{int total=0,i=0;StringBuilder b=new StringBuilder("DAILY SALES SUMMARY\\n");try(var paths=Files.list(dir)){for(Path p:paths.filter(q->q.toString().endsWith(".csv")).sorted().toList()){BufferedReader r=Files.newBufferedReader(p);opened.add(r);String line;while((line=r.readLine())!=null){if(fail&&i==1)throw new IOException("Injected failure at "+p.getFileName());if(!line.startsWith("store,"))total+=Integer.parseInt(line.split(",")[1]);}r.close();i++;}}b.append("Total sales: ").append(total).append('\n');Files.writeString(Path.of("data/manual-report.txt"),b);return b.toString();}finally{for(BufferedReader r:opened)try{r.close();}catch(IOException ignored){}}}
 static String twr(boolean fail)throws IOException{int total=0,i=0;StringBuilder b=new StringBuilder("DAILY SALES SUMMARY\\n");try(var paths=Files.list(dir)){for(Path p:paths.filter(q->q.toString().endsWith(".csv")).sorted().toList()){try(BufferedReader r=Files.newBufferedReader(p)){String line;while((line=r.readLine())!=null){if(fail&&i==1)throw new IOException("Injected failure at "+p.getFileName());if(!line.startsWith("store,"))total+=Integer.parseInt(line.split(",")[1]);}}i++;}}b.append("Total sales: ").append(total).append('\n');Files.writeString(Path.of("data/twr-report.txt"),b);return b.toString();}
 public static void main(String[]x)throws Exception{String a=manual(false),b=twr(false);System.out.print(a);System.out.println("Reports identical: "+a.equals(b));try{manual(true);}catch(IOException e){System.out.println("Manual failure: "+e.getMessage()+"; explicit finally closes readers");}try{twr(true);}catch(IOException e){System.out.println("TWR failure: "+e.getMessage()+"; resources closed automatically");}}
}